{\n
  "additionalProperties": true, \n
  "type": "object", \n
  "description": "Write result or validation error.", \n
  "properties": {\n
    "status": {\n
      "type": "string"\n
    }, \n
    "relative_url": {\n
      "type": "string"\n
    }, \n
    "status_code": {\n
      "type": [\n
        "integer", \n
        "string"\n
      ]\n
    }, \n
    "field_errors": {\n
      "type": "object"\n
    }, \n
    "missing_fields": {\n
      "type": "array"\n
    }, \n
    "error": {\n
      "type": "string", \n
      "description": "Error message; present only on failure."\n
    }\n
  }\n
}

{
 "additionalProperties": false, 
 "required": [
 "relative_url"
 ], 
 "type": "object", 
 "properties": {
 "field_values": {
 "default": {}, 
 "type": "object", 
 "description": "Map of field_my_xxx -> value."
 }, 
 "skip_validation": {
 "default": false, 
 "type": [
 "boolean", 
 "integer"
 ], 
 "description": "Skip the check this tool makes before sending, that every key names a field of the form and that the field is editable. It does NOT switch off ERP5 validation, constraints or workflow guards - those run either way. Use it when you know the form better than the check does; the write itself is unaffected."
 }, 
 "form_id": {
 "default": null, 
 "type": [
 "string", 
 "null"
 ], 
 "description": "View/form id (default view)."
 }, 
 "relative_url": {
 "type": "string", 
 "description": "Document path."
 }
 }
 }
